mapper.select:
SELECT a.tenant_id,a.project_id,a.audit_id,a.subject_id,a.action,a.result,a.reason_code,a.request_id,a.trace_id,a.schema_version,a.schema_manifest_sha256 AS schema_manifest,a.created_by,a.created_at,a.classification,OCTET_LENGTH(a.resource_ref) AS payload_bytes
FROM audit_event a
WHERE a.project_id=#{projectId} AND a.action=#{action} AND a.action='document.revision.saved' AND a.created_at >= #{from} AND a.created_at < #{to}
AND a.subject_id=#{actorId}
AND (a.created_at < #{afterCreatedAt} OR (a.created_at=#{afterCreatedAt} AND a.audit_id < #{afterAuditId}))AND 1=0
ORDER BY a.created_at DESC,a.audit_id DESC LIMIT #{limit}

SELECT o.operation_id,o.request_sha256,o.subject_id,o.operation_name,o.state,o.http_status,o.error_code,o.target_id,o.schema_version,o.schema_manifest_sha256 AS schema_manifest,o.created_by,o.created_at,o.classification,OCTET_LENGTH(o.response_ref) AS response_bytes
FROM audit_event a LEFT JOIN operation_record o ON o.tenant_id=a.tenant_id AND o.operation_id=#{operationId}
WHERE a.project_id=#{projectId} AND a.audit_id=#{auditId} AND a.action='document.revision.saved'

SELECT CASE WHEN OCTET_LENGTH(o.response_ref) <= #{maximumPayloadBytes} THEN o.response_ref ELSE NULL END
FROM audit_event a LEFT JOIN operation_record o ON o.tenant_id=a.tenant_id AND o.operation_id=#{operationId}
WHERE a.project_id=#{projectId} AND a.audit_id=#{auditId} AND a.action='document.revision.saved'

SELECT r.project_id AS revision_project_id,r.document_id AS revision_document_id,r.document_revision,r.snapshot_id AS revision_snapshot_id,r.body_sha256 AS revision_body_sha256,
m.project_id AS metadata_project_id,m.document_id AS metadata_document_id,m.document_revision AS metadata_revision,m.snapshot_id AS metadata_snapshot_id,m.body_sha256 AS metadata_body_sha256,m.content_sha256 AS metadata_content_sha256,m.based_on_document_revision AS based_on_revision,m.created_by,m.created_at,m.classification,
v.version_id,v.owner_project_id AS version_project_id,v.entity_kind AS version_kind,v.content_sha256 AS version_content_sha256,d.project_id AS owner_project_id,d.document_id AS owner_document_id
FROM audit_event a
LEFT JOIN document_revision r ON r.tenant_id=a.tenant_id AND r.project_id=a.project_id AND r.document_revision=#{documentRevision}
LEFT JOIN document_revision_meta m ON m.tenant_id=a.tenant_id AND m.project_id=a.project_id AND m.document_revision=#{documentRevision}
LEFT JOIN version_registry v ON v.tenant_id=a.tenant_id AND v.version_id=#{documentRevision}
LEFT JOIN document_head d ON d.tenant_id=a.tenant_id AND d.project_id=a.project_id AND d.document_id=#{documentId}
WHERE a.project_id=#{projectId} AND a.audit_id=#{auditId} AND a.action='document.revision.saved'

SELECT r.review_id FROM review_decision r
JOIN document_revision_meta m ON m.tenant_id=r.tenant_id AND m.project_id=r.project_id AND m.document_revision=r.document_revision
WHERE r.project_id=#{projectId} AND m.document_id=#{documentId} AND r.document_revision=#{documentRevision}
ORDER BY r.review_id LIMIT #{limit}
